INSERT OR REPLACE INTO posts (id, author_id, title_id, title_ja, slug, excerpt_id, excerpt_ja, content_id, content_ja, cover_media_id, status, seo_title_id, seo_title_ja, meta_description_id, meta_description_ja, view_count, published_at, created_at, updated_at)
VALUES ('post-01', 'a2cbebbe-723a-4b08-8700-c28e7d1b8597', 'Panduan Lengkap Lolos JFT-Basic A2 Dalam 3 Bulan Persiapan Intensif', '3ヶ月で合格するJFT-Basic A2攻略法：聴解と文字語彙の重点対策', 'panduan-jft-basic-a2', 'Strategi menguasai soal listening dan vocabulary kanji paling sering muncul pada ujian bahasa Jepang JFT-Basic A2 untuk program Tokutei Ginou.', '出題傾向を徹底分析し、短期間でスコアを伸ばすための効率的な反復学習メソッドと模擬試験の活用法を解説。', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Ujian Japan Foundation Test for Basic Japanese (JFT-Basic) A2 merupakan salah satu syarat mutlak bagi calon peserta yang ingin mengajukan visa Tokutei Ginou (Specified Skilled Worker) di Jepang."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"1. Pahami Struktur 4 Bagian Ujian"}]},{"type":"paragraph","content":[{"type":"text","text":"Ujian JFT-Basic berbasis komputer (CBT) berdurasi 60 menit dengan total sekitar 50–60 soal, terbagi menjadi: Huruf & Kosakata, Percakapan & Ungkapan, Mendengarkan (Listening), serta Membaca (Reading)."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"Fokus utama JFT-Basic bukan menguji hafalan tata bahasa rumit, melainkan kemampuan berkomunikasi praktis dalam situasi kehidupan sehari-hari di Jepang."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"2. Kuasai Kosakata Kerja & Kehidupan Harian"}]},{"type":"paragraph","content":[{"type":"text","text":"Di LPK Saindo, siswa dilatih menggunakan buku standar Irodori: Japanese for Life in Japan. Kosakata yang dipelajari langsung berorientasi pada interaksi riil di tempat kerja, supermarket, stasiun kereta, dan kantor pemerintahan Jepang."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"3. Latihan Try-Out Komputer Setiap Akhir Pekan"}]},{"type":"paragraph","content":[{"type":"text","text":"Kunci keberhasilan 98% siswa Saindo adalah pembiasaan simulasi komputer mingguan. Ini menghilangkan rasa gugup terhadap batas waktu hitung mundur layar ujian."}]}]}', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"国際交流基金日本語基礎テスト（JFT-Basic）A2は、特定技能1号の在留資格取得において必須の日本語試験です。"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"1. 4つのセクション構成の理解"}]},{"type":"paragraph","content":[{"type":"text","text":"試験はCBT方式で実施され、文字・語彙、会話・表現、聴解、読解の4分野から構成されます。日常会話での実践的な運用能力が重視されます。"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"単なる暗記ではなく、日本の職場や生活現場で即座に使えるコミュニケーション力が合否を分けます。"}]}]}]}', 'med-02', 'published', 'Panduan Lolos JFT-Basic A2 Dalam 3 Bulan — LPK Saindo', 'JFT-Basic A2対策ガイド — LPK Saindo', 'Tips dan strategi intensif lulus ujian JFT-Basic A2 untuk syarat visa Tokutei Ginou ke Jepang.', '特定技能ビザ取得のためのJFT-Basic A2合格ノウハウと学習カリキュラム。', 128, '2026-11-10T08:00:00.000Z', '2026-11-10T15:01:52.992Z', '2026-11-10T15:01:52.992Z');
