INSERT OR REPLACE INTO posts (id, author_id, title_id, title_ja, slug, excerpt_id, excerpt_ja, content_id, content_ja, cover_media_id, status, seo_title_id, seo_title_ja, meta_description_id, meta_description_ja, view_count, published_at, created_at, updated_at)
VALUES ('post-02', 'a2cbebbe-723a-4b08-8700-c28e7d1b8597', 'Peluang Kerja Tokutei Ginou Kaigo di Tokyo: Fasilitas & Standar Gaji 2026', '特定技能 介護分野（東京都）：2026年度募集要項および福利厚生', 'tokutei-ginou-kaigo-tokyo', 'Ulasan mendalam mengenai benefit, fasilitas asrama, dan jenjang karier tenaga perawat lansia profesional (Kaigo) di Tokyo dan sekitarnya.', '都内特別養護老人ホームでの就労条件、宿舎手当、資格取得支援制度についての最新情報。', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sektor Kaigo (perawat lansia) di Jepang terus membuka kesempatan emas bagi tenaga kerja terampil asal Indonesia dengan standar remunerasi yang setara dengan pekerja lokal Jepang."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Standar Penghasilan & Benefit di Tokyo"}]},{"type":"paragraph","content":[{"type":"text","text":"Gaji pokok tenaga Kaigo Tokutei Ginou di Tokyo pada tahun 2026 berkisar antara ¥210.000 hingga ¥250.000 per bulan (setara Rp 22–27 juta), belum termasuk tunjangan shift malam, lembur, dan bonus tahunan."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"Selain penghasilan yang kompetitif, banyak institusi mitra Saindo menyediakan asrama bersubsidi penuh dan bimbingan sertifikasi Kaigofukushishi nasional."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Persiapan di LPK Saindo"}]},{"type":"paragraph","content":[{"type":"text","text":"Siswa program Kaigo dibekali pelatihan etika mendampingi lansia, kosakata istilah medis Jepang, dan simulasi mengangkat pasien secara ergonomis."}]}]}', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"日本の介護現場における特定技能外国人の受入れは年々拡大しており、インドネシア人材の丁寧で温かいケアが高く評価されています。"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"東京都内での待遇と福利厚生"}]},{"type":"paragraph","content":[{"type":"text","text":"基本給は月額21万円〜25万円前後で、夜勤手当・資格手当・賞与が別途支給されます。宿舎補助や介護福祉士資格取得支援も充実しています。"}]}]}', 'med-03', 'published', 'Gaji & Peluang Kerja Tokutei Ginou Kaigo di Tokyo — LPK Saindo', '特定技能 介護職（東京都）求人情報 — LPK Saindo', 'Informasi lengkap gaji, fasilitas, dan syarat kerja Tokutei Ginou Kaigo di Tokyo Jepang.', '東京都内の介護施設における特定技能1号の最新待遇と研修受入実績。', 128, '2026-11-05T08:00:00.000Z', '2026-11-10T15:01:52.992Z', '2026-11-10T15:01:52.992Z');
