INSERT OR REPLACE INTO posts (id, author_id, title_id, title_ja, slug, excerpt_id, excerpt_ja, content_id, content_ja, cover_media_id, status, seo_title_id, seo_title_ja, meta_description_id, meta_description_ja, view_count, published_at, created_at, updated_at)
VALUES ('post-03', 'a2cbebbe-723a-4b08-8700-c28e7d1b8597', 'Mengenal Prinsip Horenso: Kunci Keberhasilan Bekerja di Perusahaan Jepang', '日本の職場で必須となる「報連相（ほうれんそう）」の真髄と実践法', 'prinsip-horenso-jepang', 'Mengapa konsep Houkoku (lapor), Renraku (komunikasi), dan Soudan (konsultasi) sangat krusial bagi pekerja asing agar disegani atasan di Jepang.', '報告・連絡・相談がなぜ日本企業で重要視されるのか、実例を交えてわかりやすくレクチャー。', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bekerja di Jepang bukan hanya soal mahir berbicara bahasa Jepang, melainkan bagaimana Anda berintegrasi dengan budaya kerja tim yang sangat menghargai alur informasi teratur."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Apa itu Horenso?"}]},{"type":"paragraph","content":[{"type":"text","text":"Horenso adalah singkatan dari tiga kata penting:"}]},{"type":"paragraph","content":[{"type":"text","text":"1. Houkoku (報告 - Laporan): Selalu laporkan progres pekerjaan sebelum ditanya oleh atasan, terutama bila ada kendala atau perubahan jadwal."}]},{"type":"paragraph","content":[{"type":"text","text":"2. Renraku (連絡 - Komunikasi/Pemberitahuan): Sampaikan informasi relevan kepada seluruh anggota tim tanpa menambah opini subjektif."}]},{"type":"paragraph","content":[{"type":"text","text":"3. Soudan (相談 - Konsultasi): Mintalah saran kepada senior atau atasan sebelum mengambil keputusan sendiri jika Anda merasa ragu."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"Di LPK Saindo, budaya Horenso dipraktikkan langsung dalam rutinitas harian asrama dari bangun pagi hingga laporan piket malam."}]}]}]}', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"「報連相」は日本のビジネスカルチャーの根幹をなすコミュニケーション原則です。"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"報連相がもたらす信頼関係"}]},{"type":"paragraph","content":[{"type":"text","text":"迅速な報告、正確な連絡、そして的確な相談を行うことで、ミスを未然に防ぎ、上司や同僚との強固な信頼関係を築くことができます。"}]}]}', 'med-04', 'published', 'Prinsip Budaya Horenso di Perusahaan Jepang — LPK Saindo', '日本のビジネスマナー「報連相」の基本 — LPK Saindo', 'Panduan prinsip kerja Horenso di perusahaan Jepang bagi magang dan tenaga kerja SSW.', '外国人材が日本企業で信頼されるための報連相の実践ポイント。', 128, '2026-10-28T08:00:00.000Z', '2026-11-10T15:01:52.992Z', '2026-11-10T15:01:52.992Z');
