INSERT OR REPLACE INTO posts (id, author_id, title_id, title_ja, slug, excerpt_id, excerpt_ja, content_id, content_ja, cover_media_id, status, seo_title_id, seo_title_ja, meta_description_id, meta_description_ja, view_count, published_at, created_at, updated_at)
VALUES ('post-04', 'a2cbebbe-723a-4b08-8700-c28e7d1b8597', 'Pelepasan 25 Siswa LPK Saindo Angkatan 14 Menuju Osaka dan Nagoya', '第14期生25名 大阪・名古屋受入企業への壮行式を挙行', 'pelepasan-siswa-angkatan-14', 'Suasana haru dan bangga saat 25 talenta muda LPK Saindo resmi diberangkatkan untuk memulai karier di industri manufaktur dan pengolahan makanan.', '4ヶ月にわたる全寮制研修を修了した優秀な第14期生が、日本への旅立ちを迎えました。', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sebanyak 25 peserta pelatihan LPK Saindo Angkatan 14 resmi dilepas dalam upacara khidmat di aula pusat pelatihan sebelum bertolak ke Bandara Internasional Soekarno-Hatta menuju Osaka dan Nagoya."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Hasil Evaluasi Pelatihan"}]},{"type":"paragraph","content":[{"type":"text","text":"Seluruh peserta telah menuntaskan kurikulum intensif 4 bulan di asrama, lulus ujian bahasa Jepang tingkat N4/JFT-Basic, dan mengantongi sertifikat kompetensi kejuruan."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"Direktur LPK Saindo berpesan agar siswa senantiasa menjaga nama baik bangsa Indonesia, menjaga shisei (sikap disiplin), dan giat menabung demi masa depan keluarga."}]}]}]}', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"大阪および名古屋の受入企業様へ派遣される第14期生25名の壮行式が、厳粛な雰囲気の中で執り行われました。"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"万全の準備で日本へ"}]},{"type":"paragraph","content":[{"type":"text","text":"実習生全員が健康診断をクリアし、生活マナーと防災訓練も修了。今後の日本での活躍が期待されます。"}]}]}', 'med-05', 'published', 'Upacara Pelepasan Siswa Saindo Angkatan 14 — LPK Saindo', '第14期生壮行式 — LPK Saindo', 'Pelepasan resmi 25 siswa LPK Saindo menuju penempatan kerja di Osaka dan Nagoya Jepang.', 'LPK Saindo第14期生の渡航壮行式と日本企業への配属報告。', 128, '2026-10-15T08:00:00.000Z', '2026-11-10T15:01:52.992Z', '2026-11-10T15:01:52.992Z');
